<?php
declare(strict_types=1);
namespace Tests\Integration;
use PDO;use PHPUnit\Framework\TestCase;
require_once dirname(__DIR__,2).'/includes/club_expenses.php';
final class ClubExpensesTest extends TestCase {
 private PDO $p;
 protected function setUp():void{$this->p=new PDO('sqlite::memory:',null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);$this->p->exec("CREATE TABLE treneri(id INTEGER PRIMARY KEY,aktivni INT);INSERT INTO treneri VALUES(1,1),(2,1),(3,1);CREATE TABLE sportovci(id INT PRIMARY KEY);INSERT INTO sportovci VALUES(5);CREATE TABLE staff_user_positions(trainer_id INT,position_code TEXT);INSERT INTO staff_user_positions VALUES(1,'finance_manager'),(2,'finance_manager'),(3,'coach');CREATE TABLE staff_superadmins(trainer_id INT);CREATE TABLE ucto_udalosti(id INT PRIMARY KEY,stav TEXT);INSERT INTO ucto_udalosti VALUES(1,'otevrena');CREATE TABLE ucto_uctenky(id INT PRIMARY KEY,udalost_id INT,obrazek_path TEXT);CREATE TABLE club_events(id INT PRIMARY KEY);INSERT INTO club_events VALUES(1)");foreach(['20261022220000_accounting_ledger','20261023050000_club_expenses','20261023100000_club_payment_returns'] as $m){$migration=require dirname(__DIR__,2).'/migrations/'.$m.'.php';$migration['up']($this->p);self::assertTrue($migration['verify']($this->p));}\accountingLedgerCreateAccount($this->p,['code'=>'CASH','name'=>'TEST cash','kind'=>'cash','opened_on'=>'2026-01-01','opening_minor'=>1000000,'evidence'=>'TEST opening evidence'],1,'TEST financial evidence',true);}
 private function input(array $replace=[]):array{return array_replace(['supplier'=>'TEST supplier','document_number'=>'TEST-1','document_on'=>'2026-10-01','due_on'=>'2026-10-31','amount_minor'=>120000,'funding_source'=>'personal','payer_kind'=>'trainer','payer_id'=>3,'payer_label'=>'TEST coach','creditor_kind'=>'trainer','creditor_id'=>3,'creditor_label'=>'TEST coach','payee_evidence'=>'TEST cash handoff signed','purpose'=>'TEST event transport','document_evidence'=>'TEST paper folder A','request_key'=>'claim-1','items'=>[['amount_minor'=>100000,'accepted'=>true,'activity'=>'club','purpose'=>'Transport'],['amount_minor'=>20000,'accepted'=>false,'activity'=>'personal','purpose'=>'Personal costs']]],$replace);}
 private function claim(array $replace=[]):array{return \clubExpenseCreateClaim($this->p,$this->input($replace),1,'TEST claim created evidence',true);}
 private function approve(array $r):array{\clubExpenseClaimTransition($this->p,(int)$r['id'],'submit',1,'TEST submit evidence',true);return \clubExpenseClaimTransition($this->p,(int)$r['id'],'approve',2,'TEST approved independently',true);}
 private function movement(int $amount,string $key):array{return \accountingLedgerRecord($this->p,['account_id'=>1,'kind'=>$amount>0?'income':'expense','amount_minor'=>$amount,'currency'=>'CZK','effective_on'=>'2026-10-02','source_context'=>'TEST','source_reference'=>$key,'request_key'=>$key,'evidence'=>'TEST actual bank statement'],1,'TEST actual proved transfer',true);}
 private function allocation(string $type,int $id,int $movement,int $amount,string $key,?int $reverse=null):array{return \clubExpenseAllocate($this->p,$type,$id,$movement,$amount,$key,'2026-10-02',1,'TEST confirmed allocation',true,$reverse);}
 private function deny(callable $f):void{try{$f();self::fail('Expected denial');}catch(\DomainException|\ClubExpenseException|\AccountingLedgerException|\FinancialEventConflict $e){self::assertNotSame('',$e->getMessage());}}
 private function case():array{return \clubExpenseCreateCase($this->p,['legacy_event_id'=>1,'club_event_id'=>1,'leader_trainer_id'=>3,'title'=>'TEST camp','due_on'=>'2026-10-31','evidence'=>'TEST verified event linkage'],1,'TEST create linked event',true);}
 private function advance(int $case,int $amount=500000):array{$r=\clubExpenseCreateAdvance($this->p,['case_id'=>$case,'recipient_kind'=>'trainer','recipient_id'=>3,'recipient_label'=>'TEST coach','payee_evidence'=>'TEST handoff proof','limit_minor'=>$amount,'due_on'=>'2026-10-31','purpose'=>'TEST camp costs','request_key'=>'advance-'.bin2hex(random_bytes(4))],1,'TEST requested advance',true);return \clubExpenseAdvanceTransition($this->p,(int)$r['id'],'approve',2,'TEST independent approval',true);}
 public function testPartialExpensesAndExactRetryNeverCreateMoreMoney():void{$r=$this->approve($this->claim());$m=$this->movement(-60000,'out-1');$a=$this->allocation('expense_claim',(int)$r['root_id'],(int)$m['id'],60000,'a-1');self::assertSame($a,$this->allocation('expense_claim',(int)$r['root_id'],(int)$m['id'],60000,'a-1'));self::assertSame(40000,\clubExpenseClaimBalance($this->p,(int)$r['id'])['remaining_minor']);$this->deny(fn()=>$this->allocation('expense_claim',(int)$r['id'],(int)$m['id'],1,'a-over'));$n=$this->movement(-50000,'out-2');$this->deny(fn()=>$this->allocation('expense_claim',(int)$r['id'],(int)$n['id'],50000,'claim-over'));$this->allocation('expense_claim',(int)$r['id'],(int)$n['id'],40000,'a-2');self::assertSame(0,\clubExpenseClaimBalance($this->p,(int)$r['id'])['remaining_minor']);self::assertSame(2,(int)$this->p->query('SELECT COUNT(*) FROM accounting_movements')->fetchColumn());}
 public function testApprovalIsIndependentAndVersionsAreImmutable():void{$r=$this->claim();$this->deny(fn()=>\clubExpenseClaimTransition($this->p,(int)$r['id'],'approve',2,'TEST approval before submit',true));\clubExpenseClaimTransition($this->p,(int)$r['id'],'submit',1,'TEST submit evidence',true);$this->deny(fn()=>\clubExpenseClaimTransition($this->p,(int)$r['id'],'approve',1,'TEST self approval evidence',true));\clubExpenseClaimTransition($this->p,(int)$r['id'],'approve',2,'TEST independent approval',true);$this->deny(fn()=>\clubExpenseClaimTransition($this->p,(int)$r['id'],'approve',2,'TEST duplicate approval',true));$copy=$this->claim(['previous_id'=>$r['id'],'request_key'=>'claim-v2','items'=>[['amount_minor'=>120000,'accepted'=>true,'activity'=>'club','purpose'=>'Correct approved scope']]]);$this->approve($copy);self::assertSame('superseded',\clubExpenseOne($this->p,'club_expense_claims',(int)$r['id'])['state']);self::assertSame(100000,(int)\clubExpenseOne($this->p,'club_expense_claims',(int)$r['id'])['accepted_minor']);self::assertSame(120000,\clubExpenseClaimBalance($this->p,(int)$r['id'])['approved_minor']);}
 public function testDuplicateSplitForeignCurrencyAndRevokedRole():void{$r=$this->claim();self::assertSame($r,$this->claim());$this->deny(fn()=>$this->claim(['request_key'=>'duplicate']));$this->deny(fn()=>$this->claim(['request_key'=>'wrong-sum','amount_minor'=>120001]));$this->deny(fn()=>$this->claim(['request_key'=>'foreign-no-evidence','original_currency'=>'EUR','original_amount_minor'=>4800]));$f=$this->claim(['request_key'=>'foreign','document_number'=>'EUR-1','original_currency'=>'EUR','original_amount_minor'=>4800,'conversion_evidence'=>'TEST actual booked rate 25 CZK']);self::assertSame('EUR',$f['original_currency']);$this->p->exec('DELETE FROM staff_user_positions WHERE trainer_id=1');$this->deny(fn()=>$this->claim(['request_key'=>'revoked']));}
 public function testAdvanceSettlementRequiresRealReturnsAndSeparateSources():void{$case=$this->case();$a=$this->advance((int)$case['id']);self::assertSame(0,\clubExpenseAdvanceBalance($this->p,(int)$a['id'])['out_minor']);$m=$this->movement(-500000,'advance-out');$this->allocation('expense_advance_out',(int)$a['id'],(int)$m['id'],500000,'handoff');$r=$this->approve($this->claim(['case_id'=>$case['id'],'amount_minor'=>420000,'funding_source'=>'advance','items'=>[['amount_minor'=>420000,'accepted'=>true,'activity'=>'club','purpose'=>'Camp']]]));$this->deny(fn()=>$this->allocation('expense_claim',(int)$r['id'],(int)$m['id'],420000,'double-expense'));$used=\clubExpenseConsume($this->p,(int)$r['id'],(int)$a['id'],420000,'consume','2026-10-02',1,'TEST consumed actual receipt',true);self::assertSame(80000,\clubExpenseAdvanceBalance($this->p,(int)$a['id'])['balance_minor']);$this->deny(fn()=>\clubExpenseAdvanceTransition($this->p,(int)$a['id'],'close',1,'TEST premature close',true));$this->deny(fn()=>\clubExpenseConsume($this->p,(int)$r['id'],(int)$a['id'],1,'extra','2026-10-02',1,'TEST duplicate consumption',true));foreach([50000,30000] as $i=>$n){$m=$this->movement($n,'return-'.$i);$this->allocation('expense_advance_in',(int)$a['id'],(int)$m['id'],$n,'return-alloc-'.$i);}self::assertSame(0,\clubExpenseAdvanceBalance($this->p,(int)$a['id'])['balance_minor']);\clubExpenseAdvanceTransition($this->p,(int)$a['id'],'close',1,'TEST settled advance',true);\clubExpenseCloseCase($this->p,(int)$case['id'],1,'TEST settled case closed',true);self::assertSame('uzavrena',$this->p->query('SELECT stav FROM ucto_udalosti WHERE id=1')->fetchColumn());$this->deny(fn()=>\clubExpenseConsume($this->p,(int)$r['id'],(int)$a['id'],-420000,'reverse','2026-10-02',1,'TEST closed correction',true,(int)$used['id']));}
 public function testOverdrawnAdvanceNeedsApprovedSupplementAndTransfer():void{$case=$this->case();$a=$this->advance((int)$case['id'],200000);$m=$this->movement(-200000,'advance-out');$this->allocation('expense_advance_out',(int)$a['id'],(int)$m['id'],200000,'handoff');$r=$this->approve($this->claim(['case_id'=>$case['id'],'amount_minor'=>230000,'funding_source'=>'advance','items'=>[['amount_minor'=>230000,'accepted'=>true,'activity'=>'club','purpose'=>'Camp']]]));\clubExpenseConsume($this->p,(int)$r['id'],(int)$a['id'],230000,'consume','2026-10-02',1,'TEST actual overdraw',true);self::assertSame(-30000,\clubExpenseAdvanceBalance($this->p,(int)$a['id'])['balance_minor']);$extra=$this->advance((int)$case['id'],30000);$m=$this->movement(-30000,'supplement');$this->allocation('expense_advance_out',(int)$extra['id'],(int)$m['id'],30000,'supplement-alloc');\clubExpenseTransferAdvance($this->p,(int)$extra['id'],(int)$a['id'],30000,'supplement-transfer','2026-10-02','TEST approved supplemental settlement',1,'TEST supplemented cash deficit',true);self::assertSame(0,\clubExpenseAdvanceBalance($this->p,(int)$a['id'])['balance_minor']);self::assertSame(0,\clubExpenseAdvanceBalance($this->p,(int)$extra['id'])['balance_minor']);}
 public function testLinkedLegacyReceiptAndEventCannotBypassVersioning():void{$c=$this->case();$this->p->exec("INSERT INTO ucto_uctenky VALUES(1,1,'')");$r=$this->claim(['case_id'=>$c['id'],'receipt_id'=>1]);$this->p->beginTransaction();$this->deny(fn()=>\financialReceiptAssertMutable($this->p,['id'=>1,'udalost_id'=>1],null));$this->deny(fn()=>\financialEventAssertLegacyMutable($this->p,1));$this->p->rollBack();$this->deny(fn()=>\clubExpenseCloseCase($this->p,(int)$c['id'],1,'TEST pending receipt blocks close',true));}
 public function testAllocationCorrectionDoesNotRewriteOriginalPayment():void{$r=$this->approve($this->claim());$m=$this->movement(-60000,'out');$a=$this->allocation('expense_claim',(int)$r['id'],(int)$m['id'],60000,'pay');$this->allocation('expense_claim',(int)$r['id'],(int)$m['id'],-60000,'release',(int)$a['id']);self::assertSame(100000,\clubExpenseClaimBalance($this->p,(int)$r['id'])['remaining_minor']);self::assertSame(-60000,(int)$this->p->query('SELECT amount_minor FROM accounting_movements')->fetchColumn());$this->deny(fn()=>$this->allocation('expense_claim',(int)$r['id'],(int)$m['id'],-1,'over-release',(int)$a['id']));}
 public function testDownwardPaidCorrectionRequiresActualRefundAndCannotReleaseItAway():void {
  $r=$this->approve($this->claim());$m=$this->movement(-60000,'paid');$a=$this->allocation('expense_claim',(int)$r['id'],(int)$m['id'],60000,'paid-alloc');
  $v=$this->approve($this->claim(['previous_id'=>$r['id'],'request_key'=>'downward','items'=>[['amount_minor'=>40000,'accepted'=>true,'activity'=>'club','purpose'=>'Corrected scope'],['amount_minor'=>80000,'accepted'=>false,'activity'=>'personal','purpose'=>'Rejected remainder']]]));
  self::assertSame(-20000,\clubExpenseClaimBalance($this->p,(int)$r['id'])['remaining_minor']);$this->deny(fn()=>$this->allocation('expense_claim',(int)$r['id'],(int)$m['id'],-20000,'fake-refund',(int)$a['id']));
  $back=$this->movement(20000,'actual-refund');$ret=$this->allocation('expense_claim_return',(int)$r['id'],(int)$back['id'],20000,'actual-refund-alloc');self::assertSame(0,\clubExpenseClaimBalance($this->p,(int)$r['id'])['remaining_minor']);self::assertSame(40000,\clubExpenseClaimBalance($this->p,(int)$r['id'])['net_paid_minor']);self::assertSame($ret,$this->allocation('expense_claim_return',(int)$r['id'],(int)$back['id'],20000,'actual-refund-alloc'));$this->deny(fn()=>$this->allocation('expense_claim_return',(int)$r['id'],(int)$back['id'],1,'excess-refund'));
 }
 public function testReleasedPaymentCannotHideDownwardReceivable():void {
  $r=$this->approve($this->claim());$m=$this->movement(-60000,'paid');$a=$this->allocation('expense_claim',(int)$r['id'],(int)$m['id'],60000,'paid-alloc');$this->allocation('expense_claim',(int)$r['id'],(int)$m['id'],-60000,'release',(int)$a['id']);
  $v=$this->claim(['previous_id'=>$r['id'],'request_key'=>'downward','items'=>[['amount_minor'=>40000,'accepted'=>true,'activity'=>'club','purpose'=>'Corrected scope'],['amount_minor'=>80000,'accepted'=>false,'activity'=>'personal','purpose'=>'Rejected remainder']]]);$this->deny(fn()=>$this->approve($v));self::assertSame('approved',\clubExpenseOne($this->p,'club_expense_claims',(int)$r['id'])['state']);
 }
 public function testAsOfExportPreservesOldApprovedVersionAndExcludesLaterPayments():void {
  $r=$this->approve($this->claim());$this->p->exec("UPDATE club_expense_claims SET created_at='2026-10-01 10:00:00',approved_at='2026-10-02 10:00:00'");
  $m=$this->movement(-60000,'paid');$this->allocation('expense_claim',(int)$r['id'],(int)$m['id'],60000,'paid-alloc');$this->p->exec("UPDATE accounting_allocations SET effective_on='2026-10-15'");
  $v=$this->approve($this->claim(['previous_id'=>$r['id'],'request_key'=>'v2','items'=>[['amount_minor'=>120000,'accepted'=>true,'activity'=>'club','purpose'=>'Corrected scope']]]));$this->p->exec("UPDATE club_expense_claims SET created_at='2026-10-20 10:00:00',approved_at='2026-10-20 11:00:00' WHERE id=".(int)$v['id']);
  $old=\clubExpenseExportRows($this->p,'2026-10-01','2026-10-10');self::assertCount(1,$old['claims']);self::assertSame('approved',$old['claims'][0]['state']);self::assertSame(100000,$old['claims'][0]['remaining_minor']);self::assertCount(0,$old['allocations']);$now=\clubExpenseExportRows($this->p,'2026-10-01','2026-10-22');self::assertSame(1,count(array_filter($now['claims'],fn($r)=>$r['state']==='approved')));self::assertSame(60000,$now['claims'][1]['remaining_minor']);
 }

 public function testActualBankReturnReopensPaidExpenseWithoutChangingApprovedAmount():void {
  $r=$this->approve($this->claim());$out=$this->movement(-100000,'bank-return-original');$a=$this->allocation('expense_claim',(int)$r['id'],(int)$out['id'],100000,'bank-original-allocation');$in=$this->movement(100000,'bank-return-income');
  $do=fn(int $amount,string $key)=>\clubExpenseAllocate($this->p,'expense_claim_return',(int)$r['id'],(int)$in['id'],$amount,$key,'2026-10-02',1,'TEST actual bank return',true,null,(int)$a['id']);
  $part=$do(40000,'bank-return-part');self::assertSame($part,$do(40000,'bank-return-part'));self::assertSame(40000,\clubExpenseClaimBalance($this->p,(int)$r['id'])['remaining_minor']);$do(60000,'bank-return-rest');self::assertSame(100000,\clubExpenseClaimBalance($this->p,(int)$r['id'])['remaining_minor']);$this->deny(fn()=>$do(1,'bank-return-too-much'));
  $again=$this->movement(-100000,'bank-repayment');$this->allocation('expense_claim',(int)$r['id'],(int)$again['id'],100000,'bank-repayment-allocation');self::assertSame(0,\clubExpenseClaimBalance($this->p,(int)$r['id'])['remaining_minor']);self::assertSame(2,(int)$this->p->query('SELECT COUNT(*) FROM club_payment_returns')->fetchColumn());
 }
 public function testLateRecordedDocumentsRemainTraceableWithoutBackdatingApproval():void {
  $r=$this->approve($this->claim());$m=$this->movement(-100000,'late-recorded-out');$this->allocation('expense_claim',(int)$r['id'],(int)$m['id'],100000,'late-recorded-allocation');
  $this->p->exec("UPDATE club_expense_claims SET created_at='2026-10-23 12:00:00',approved_at='2026-10-23 12:00:00';UPDATE club_expense_events SET created_at='2026-10-23 12:00:00'");
  $rows=\clubExpenseExportRows($this->p,'2026-10-01','2026-10-02');self::assertCount(1,$rows['claims']);self::assertTrue($rows['claims'][0]['late_recorded']);self::assertFalse($rows['claims'][0]['is_effective_approval']);self::assertSame('historical',$rows['claims'][0]['state']);self::assertSame('TEST paper folder A',$rows['claims'][0]['document_evidence']);self::assertCount(1,$rows['allocations']);
  $a=$this->advance((int)$this->case()['id']);$out=$this->movement(-50000,'late-advance-out');$this->allocation('expense_advance_out',(int)$a['id'],(int)$out['id'],50000,'late-advance-allocation');$this->p->exec("UPDATE club_expense_advances SET created_at='2026-10-23 12:00:00'");$rows=\clubExpenseExportRows($this->p,'2026-10-01','2026-10-02');self::assertCount(1,$rows['advances']);self::assertTrue($rows['advances'][0]['late_recorded']);self::assertSame(50000,$rows['advances'][0]['balance_minor']);
 }
